import{_ as a,o as t,c as r,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"FR 3.5.3 - Request Media Package Changes","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-3-request-media-package/spec.md","filePath":"feature/media-package-campaign/3-5-3-request-media-package/spec.md"}'),i={name:"feature/media-package-campaign/3-5-3-request-media-package/spec.md"};function n(s,e,c,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="fr-3-5-3-request-media-package-changes" tabindex="-1">FR 3.5.3 - Request Media Package Changes <a class="header-anchor" href="#fr-3-5-3-request-media-package-changes" aria-label="Permalink to &quot;FR 3.5.3 - Request Media Package Changes&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Status</td><td>Ready for technical review</td></tr><tr><td>Roles</td><td>Client; Owner/Manager</td></tr><tr><td>Delivery task</td><td>DA-E50-04</td></tr></tbody></table><h2 id="outcome" tabindex="-1">Outcome <a class="header-anchor" href="#outcome" aria-label="Permalink to &quot;Outcome&quot;">​</a></h2><p>Client and Agency negotiate the selected workspace package through a durable, ordered history of requested terms and counter-offers.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Client submits <code>requestedTerms</code> and optional note through <code>request-change</code>.</li><li>Owner/Manager submits a counter-offer or response.</li><li>Status moves between <code>CLIENT_REQUESTED_CHANGE</code> and <code>AGENCY_COUNTERED</code> until both parties approve.</li><li>The package itself cannot be replaced after negotiation begins; only its workspace terms may change.</li><li>The API exposes a negotiation history for the UI thread.</li></ul><h2 id="persistence-design" tabindex="-1">Persistence design <a class="header-anchor" href="#persistence-design" aria-label="Permalink to &quot;Persistence design&quot;">​</a></h2><p><code>workspace_media_packages</code> holds current <code>final_terms</code> and <code>terms_version</code>. E50-04 adds append-only <code>package_negotiation_events</code> with the workspace package ID, terms version, actor, action (<code>REQUEST_CHANGE</code> or <code>COUNTER_OFFER</code>), terms snapshot, optional note, and timestamp. Every terms-changing event increments the version and invalidates both approvals atomically.</p><h2 id="phase-5-—-confirmed-2026-10-13" tabindex="-1">Phase 5 — confirmed 2026-10-13 <a class="header-anchor" href="#phase-5-—-confirmed-2026-10-13" aria-label="Permalink to &quot;Phase 5 — confirmed 2026-10-13&quot;">​</a></h2><ul><li>Negotiation and approval require <code>expectedTermsVersion</code> &gt;=1. Under the selection row lock a stale version returns 409 MEDIA_PACKAGE_VERSION_CONFLICT; no terms, approvals, history, notification or proposal count changes. Missing version is 400. User explicitly approved this breaking contract; Web and other API clients must update.</li><li>History contains immutable snapshots and actor role/ID, optional note &lt;=2000. Actor role uses effective Workspace membership; Agency ownership is a fallback only when no direct membership exists (Owner assigned Manager acts as Manager). A Client proposal increments clientProposalCount; Manager/Owner does not consume it. No-change/invalid/forbidden/approved-package mutations do not append history.</li><li>Legacy already-negotiated/approved selections get exactly one BASELINE at the current version, unknown actor, recording time = migration time. DRAFT selections wait until first negotiation, including those switched before negotiation. Do not infer lost events from previous_terms. For a fresh DRAFT, first successful negotiation records its prior snapshot as BASELINE then the new proposal, in the same transaction.</li><li>History is append-only while its Workspace exists (no event edit/delete API; direct SQL update/delete blocked). Preserve existing parent Workspace hard-delete cascade behavior, rather than introducing retention that blocks other modules.</li><li>GET <code>/api/v1/workspaces/{workspaceId}/media-package/history</code> is paginated, newest first, Owner/Manager/Client scoped; Creator/outsider cannot read. No selection returns 404. Read never creates a baseline.</li><li>Switching an unnegotiated package must increment (not reset) termsVersion; otherwise an old page could approve a different package using the same version.</li><li>UI adds a collapsible history beside current terms; historical snapshots are read-only, never the approval target. Reuse current old/new diff component against current terms, show baseline warning. Preserve current fonts/theme/layout.</li><li>i18n: parallel <code>mediaPackage.history.*</code> keys (title, empty, baseline, error, reload, previous, next, version, actor, note, compare, recordedAt, actions, roles). Loading/empty/error/retry, keyboard and light/dark/mobile states are required.</li></ul>',10)])])}const u=a(i,[["render",n]]);export{m as __pageData,u as default};
